union drm_vmw_gb_surface_create_arg *arg =
    (union drm_vmw_gb_surface_create_arg *)data;
struct drm_vmw_gb_surface_create_req *req = &arg->req;
struct drm_vmw_gb_surface_create_rep *rep = &arg->rep;
struct ttm_object_file *tfile = vmw_fpriv(file_priv)->tfile;
int ret;
uint32_t size;
const struct svga3d_surface_desc *desc;
uint32_t backup_handle;

if (req->mip_levels > DRM_VMW_MAX_MIP_LEVELS)
	return -EINVAL;

if (unlikely(vmw_user_surface_size == 0))
	vmw_user_surface_size = ttm_round_pot(sizeof(*user_srf)) +
		128;

size = vmw_user_surface_size + 128;

desc = svga3dsurface_get_desc(req->format);
if (unlikely(desc->block_desc == SVGA3DBLOCKDESC_NONE)) {
	DRM_ERROR("Invalid surface format for surface creation.\n");
	return -EINVAL;
}

ret = ttm_read_lock(&dev_priv->reservation_sem, true);
if (unlikely(ret != 0))
	return ret;

ret = ttm_mem_global_alloc(vmw_mem_glob(dev_priv),
			   size, false, true);
if (unlikely(ret != 0)) {
	if (ret != -ERESTARTSYS)
		DRM_ERROR("Out of graphics memory for surface"
			  " creation.\n");
	goto out_unlock;
}

user_srf = kzalloc(sizeof(*user_srf), GFP_KERNEL);
if (unlikely(user_srf == NULL)) {
	ret = -ENOMEM;
	goto out_no_user_srf;
}

srf = &user_srf->srf;
res = &srf->res;

srf->flags = req->svga3d_flags;
srf->format = req->format;
srf->scanout = req->drm_surface_flags & drm_vmw_surface_flag_scanout;
srf->mip_levels[0] = req->mip_levels;
srf->num_sizes = 1;
srf->sizes = NULL;
srf->offsets = NULL;
user_srf->size = size;
srf->base_size = req->base_size;
srf->autogen_filter = SVGA3D_TEX_FILTER_NONE;
srf->multisample_count = req->multisample_count;
res->backup_size = svga3dsurface_get_serialized_size
  (srf->format, srf->base_size, srf->mip_levels[0],
   srf->flags & SVGA3D_SURFACE_CUBEMAP);

user_srf->prime.base.shareable = false;
user_srf->prime.base.tfile = NULL;
if (drm_is_primary_client(file_priv))
	user_srf->master = drm_master_get(file_priv->master);

/**
 * From this point, the generic resource management functions
 * destroy the object on failure.
 */

ret = vmw_surface_init(dev_priv, srf, vmw_user_surface_free);
if (unlikely(ret != 0))
	goto out_unlock;

if (req->buffer_handle != SVGA3D_INVALID_ID) {
	ret = vmw_user_dmabuf_lookup(tfile, req->buffer_handle,
				     &res->backup,
				     &user_srf->backup_base);
} else if (req->drm_surface_flags &
	   drm_vmw_surface_flag_create_buffer)
	ret = vmw_user_dmabuf_alloc(dev_priv, tfile,
				    res->backup_size,
				    req->drm_surface_flags &
				    drm_vmw_surface_flag_shareable,
				    &backup_handle,
				    &res->backup,
				    &user_srf->backup_base);

if (unlikely(ret != 0)) {
	vmw_resource_unreference(&res);
	goto out_unlock;
}

tmp = vmw_resource_reference(&srf->res);
ret = ttm_prime_object_init(tfile, res->backup_size, &user_srf->prime,
			    req->drm_surface_flags &
			    drm_vmw_surface_flag_shareable,
			    VMW_RES_SURFACE,

